# --- canonical.py ----------------------------------------------------------------
CANONICAL_SCHEMA: Final[str] = "underwrite-canonical-json/v1"
SAFE_INT_MAX: Final[int] = 2**53
# ASCII lowercase letters/digits/./_/- only (tagged_digest's domain-separation tag).
_TAG_RE: Final[re.Pattern[str]] = re.compile(r"^[a-z0-9._-]+$")

_BACKSLASH: Final[str] = chr(0x5C)
_QUOTE: Final[str] = chr(0x22)
_CONTROL_CHAR_LIMIT: Final[int] = 0x20
# ECMAScript Number::toString layout boundaries (RFC 8785 number serialization).
_ES6_MAX_FIXED_EXPONENT: Final[int] = 21
_ES6_MIN_FIXED_EXPONENT: Final[int] = -6

# RFC 8785 §3.2.2.2 named escapes; every other control char < 0x20 falls
# back to "\u00xx" and everything else is emitted as literal UTF-8.
_NAMED_ESCAPES: Final[dict[str, str]] = {
    _QUOTE: _BACKSLASH + _QUOTE,
    _BACKSLASH: _BACKSLASH + _BACKSLASH,
    chr(0x08): _BACKSLASH + "b",
    chr(0x0C): _BACKSLASH + "f",
    chr(0x0A): _BACKSLASH + "n",
    chr(0x0D): _BACKSLASH + "r",
    chr(0x09): _BACKSLASH + "t",
}


class CanonicalizationError(ValueError):
    """Raised when a value cannot be serialized under CANONICAL_SCHEMA.

    ``args[0]`` is one of: NON_NFC_STRING, NON_UTF8_STRING,
    INT_OUT_OF_SAFE_RANGE, NON_FINITE_NUMBER, UNSUPPORTED_TYPE, INVALID_TAG.
    """


def canonical_bytes(value: object) -> bytes:
    """Serialize ``value`` as underwrite-canonical-json/v1 UTF-8 bytes.

    A string holding a lone surrogate is no sequence of Unicode scalar values, so it has
    no UTF-8 (or UTF-16 sort key) and is not I-JSON (RFC 7493 §2.1, which RFC 8785
    assumes): `CanonicalizationError("NON_UTF8_STRING")`, raised outside the handler so
    no codec exception is its context.
    """
    try:
        return _encode(value).encode("utf-8")
    except UnicodeEncodeError:
        pass
    raise CanonicalizationError("NON_UTF8_STRING")


def digest_bytes(data: bytes) -> str:
    """Return the ``sha256:<hex>`` digest of raw bytes."""
    return "sha256:" + hashlib.sha256(data).hexdigest()


def content_digest(value: object) -> str:
    """Return ``digest_bytes(canonical_bytes(value))``."""
    return digest_bytes(canonical_bytes(value))


def tagged_digest(tag: str, data: bytes) -> str:
    """Domain-separated ``sha256:`` digest of ``data`` under ``tag``.

    ``sha256:`` + ``sha256(len(tag_utf8) as 8-byte big-endian || tag_utf8 ||
    data).hexdigest()``. The length-prefixed tag binds ``data`` to the
    purpose it was digested for, so the same bytes digested under two
    different tags -- or two different tags whose concatenation could
    otherwise collide -- never produce the same digest.

    Raises `CanonicalizationError("INVALID_TAG")` unless ``tag`` matches
    ``^[a-z0-9._-]+$`` (ASCII lowercase letters, digits, ``.``, ``_``, ``-``).
    """
    if not _TAG_RE.fullmatch(tag):
        raise CanonicalizationError("INVALID_TAG")
    tag_bytes = tag.encode("ascii")
    header = len(tag_bytes).to_bytes(8, "big")
    return "sha256:" + hashlib.sha256(header + tag_bytes + data).hexdigest()


def _is_object_list(value: object) -> TypeGuard[list[object]]:
    """`isinstance(value, list)`, narrowed to `list[object]` (not
    `list[Unknown]`) so its elements type-check as the `object` `_encode`
    already accepts, with no `typing.cast`."""
    return isinstance(value, list)


def _is_object_dict(value: object) -> TypeGuard[dict[object, object]]:
    """`isinstance(value, dict)`, narrowed to `dict[object, object]` for the
    same reason as `_is_object_list` above."""
    return isinstance(value, dict)


def _encode(value: object) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, str):
        return _encode_string(value)
    if isinstance(value, (int, float)):
        return _encode_number(value)
    if _is_object_list(value):
        return "[" + ",".join(_encode(item) for item in value) + "]"
    if _is_object_dict(value):
        return _encode_object(value)
    raise CanonicalizationError("UNSUPPORTED_TYPE")


def _encode_number(value: int | float) -> str:
    if isinstance(value, int):
        return _encode_int(value)
    return _encode_float(value)


def _encode_string(value: str) -> str:
    if unicodedata.normalize("NFC", value) != value:
        raise CanonicalizationError("NON_NFC_STRING")
    return _QUOTE + _escape_string(value) + _QUOTE


def _escape_string(value: str) -> str:
    out: list[str] = []
    for ch in value:
        escape = _NAMED_ESCAPES.get(ch)
        if escape is not None:
            out.append(escape)
        elif ord(ch) < _CONTROL_CHAR_LIMIT:
            out.append(_BACKSLASH + "u00" + format(ord(ch), "02x"))
        else:
            out.append(ch)
    return "".join(out)


def _encode_int(value: int) -> str:
    if abs(value) > SAFE_INT_MAX:
        raise CanonicalizationError("INT_OUT_OF_SAFE_RANGE")
    return str(value)


def _encode_float(value: float) -> str:
    if math.isnan(value) or math.isinf(value):
        raise CanonicalizationError("NON_FINITE_NUMBER")
    rendered = _format_float(value)
    if "." not in rendered and "e" not in rendered and abs(value) > SAFE_INT_MAX:
        raise CanonicalizationError("INT_OUT_OF_SAFE_RANGE")
    return rendered


def _encode_object(value: dict[object, object]) -> str:
    keys: list[str] = []
    for key in value:
        if not isinstance(key, str):
            raise CanonicalizationError("UNSUPPORTED_TYPE")
        keys.append(key)
    parts = [
        _encode_string(key) + ":" + _encode(value[key])
        for key in sorted(keys, key=_member_sort_key)
    ]
    return "{" + ",".join(parts) + "}"


def _member_sort_key(key: str) -> bytes:
    """RFC 8785 §3.2.3 member ordering: compare UTF-16 code unit sequences.

    Comparing the big-endian UTF-16 byte encoding lexicographically is
    equivalent to comparing the code unit arrays numerically, because every
    code unit occupies exactly two bytes.
    """
    return key.encode("utf-16-be")


def _format_float(value: float) -> str:
    """Format a finite float per ECMAScript ``Number::toString`` (RFC 8785).

    ``repr`` already gives the shortest decimal digit string that round
    trips to ``value`` (CPython's float repr); this only re-derives the
    significant digits and decimal exponent from that string and re-lays
    them out per the ES6 rules instead of Python's own formatting choices.
    """
    if value == 0.0:
        return "0"
    negative = value < 0.0
    digits, n = _shortest_digits_and_exponent(-value if negative else value)
    k = len(digits)
    if k <= n <= _ES6_MAX_FIXED_EXPONENT:
        body = digits + "0" * (n - k)
    elif 0 < n <= _ES6_MAX_FIXED_EXPONENT:
        body = digits[:n] + "." + digits[n:]
    elif _ES6_MIN_FIXED_EXPONENT < n <= 0:
        body = "0." + "0" * (-n) + digits
    else:
        exponent = n - 1
        sign = "+" if exponent >= 0 else "-"
        mantissa = digits[0] if k == 1 else digits[0] + "." + digits[1:]
        body = mantissa + "e" + sign + str(abs(exponent))
    return "-" + body if negative else body


def _shortest_digits_and_exponent(magnitude: float) -> tuple[str, int]:
    """Return ``(digits, n)`` with no leading/trailing zeros in ``digits``,
    such that ``magnitude == int(digits) * 10 ** (n - len(digits))``.
    """
    text = repr(magnitude)
    mantissa, _, exponent_text = text.partition("e")
    exponent = int(exponent_text) if exponent_text else 0
    int_part, _, frac_part = mantissa.partition(".")
    digits = int_part + frac_part
    point = len(int_part) + exponent
    stripped = digits.lstrip("0")
    point -= len(digits) - len(stripped)
    return stripped.rstrip("0"), point


# --- chain.py --------------------------------------------------------------------
@dataclass(frozen=True)
class ChainRow:
    """One chained row: ``row_hash`` binds ``seq``/``kind``/``payload_digest``/``prev_hash``."""

    seq: int
    kind: str
    payload_digest: str
    prev_hash: str | None
    row_hash: str


def row_hash_for(seq: int, kind: str, payload_digest: str, prev_hash: str | None) -> str:
    """``content_digest`` of the row's chained fields under schema ``chain_row.v1``."""
    return content_digest(
        {
            "schema": "chain_row.v1",
            "seq": seq,
            "kind": kind,
            "payload_digest": payload_digest,
            "prev_hash": prev_hash,
        }
    )


def append_row(rows: Sequence[ChainRow], kind: str, payload_digest: str) -> ChainRow:
    """Build the next `ChainRow` after ``rows`` (``seq`` 0 and ``prev_hash`` `None` if empty)."""
    last = rows[-1] if rows else None
    seq = last.seq + 1 if last is not None else 0
    prev_hash = last.row_hash if last is not None else None
    row_hash = row_hash_for(seq, kind, payload_digest, prev_hash)
    return ChainRow(
        seq=seq, kind=kind, payload_digest=payload_digest, prev_hash=prev_hash, row_hash=row_hash
    )


class ChainReason(Enum):
    """Canonical `verify_chain` outcomes."""

    OK = "OK"
    CHAIN_EDIT = "CHAIN_EDIT"
    CHAIN_GAP = "CHAIN_GAP"
    CHAIN_TRUNCATED = "CHAIN_TRUNCATED"
    CHAIN_HEAD_MISMATCH = "CHAIN_HEAD_MISMATCH"
    ANCHOR_INVALID = "ANCHOR_INVALID"


@dataclass(frozen=True)
class ChainVerdict:
    """The outcome of one `verify_chain` call. ``at_seq`` is `None` only when ``ok``."""

    ok: bool
    reason: ChainReason
    at_seq: int | None


@dataclass(frozen=True)
class AnchorRecord:
    """Pins a chain's length and head hash."""

    upto_seq: int
    chain_hash: str
    schema: str = "anchor.v1"


def anchor_for(rows: Sequence[ChainRow]) -> AnchorRecord:
    """Anchor at the last row of ``rows``. ``rows`` must be non-empty."""
    last = rows[-1]
    return AnchorRecord(upto_seq=last.seq, chain_hash=last.row_hash)


def verify_chain(rows: Sequence[ChainRow], *, anchor: AnchorRecord | None = None) -> ChainVerdict:
    """Verify ``rows`` are a contiguous, correctly hashed chain from ``seq`` 0.

    Walks ``rows`` in order: a ``seq`` that skips ahead or a ``prev_hash``
    that does not equal the previous row's ``row_hash`` is a missing/
    reordered row (`CHAIN_GAP` at the first row where this is detected); a
    ``row_hash`` that does not match `row_hash_for` recomputed from that
    row's own fields is an in-place edit (`CHAIN_EDIT` at that row's
    ``seq``). When ``anchor`` is given, an internally consistent chain that
    does not reach ``anchor.upto_seq`` is a truncated/replaced tail
    (`CHAIN_TRUNCATED`); one that reaches it but whose row there hashes to
    something other than ``anchor.chain_hash`` is a rewritten head
    (`CHAIN_HEAD_MISMATCH`) -- both reported at ``anchor.upto_seq``. A negative
    ``anchor.upto_seq`` is rejected outright as `ANCHOR_INVALID` before any
    indexing, since Python's negative-index wraparound would otherwise alias
    an existing row (or raise `IndexError` on an empty chain).
    """
    expected_prev: str | None = None
    for index, row in enumerate(rows):
        if row.seq != index or row.prev_hash != expected_prev:
            return ChainVerdict(ok=False, reason=ChainReason.CHAIN_GAP, at_seq=index)
        if row_hash_for(row.seq, row.kind, row.payload_digest, row.prev_hash) != row.row_hash:
            return ChainVerdict(ok=False, reason=ChainReason.CHAIN_EDIT, at_seq=row.seq)
        expected_prev = row.row_hash

    if anchor is not None:
        if anchor.upto_seq < 0:
            return ChainVerdict(ok=False, reason=ChainReason.ANCHOR_INVALID, at_seq=anchor.upto_seq)
        last_seq = rows[-1].seq if rows else -1
        if last_seq < anchor.upto_seq:
            return ChainVerdict(
                ok=False, reason=ChainReason.CHAIN_TRUNCATED, at_seq=anchor.upto_seq
            )
        if rows[anchor.upto_seq].row_hash != anchor.chain_hash:
            return ChainVerdict(
                ok=False, reason=ChainReason.CHAIN_HEAD_MISMATCH, at_seq=anchor.upto_seq
            )

    return ChainVerdict(ok=True, reason=ChainReason.OK, at_seq=None)


# --- bundle.py -------------------------------------------------------------------
_INDEX_PATH = "index.json"
_MANIFEST_PATH = "manifest-sha256.txt"
_BLOB_PATH_RE = re.compile(r"^blobs/sha256/([0-9a-f]{64})$")
_DIGEST_RE = re.compile(r"^sha256:[0-9a-f]{64}$")


class BundleError(ValueError):
    """Raised when planning fails; ``args[0]`` is one of: DUPLICATE_ROLE."""


@dataclass(frozen=True)
class Blob:
    """One artifact to place in the bundle, content-addressed by its `data`."""

    role: str
    media_type: str
    data: bytes


@dataclass(frozen=True)
class Descriptor:
    """One `index.json` entry: the role, media type, digest, and size it claims."""

    role: str
    media_type: str
    digest: str
    size: int


@dataclass(frozen=True)
class ExpectedSet:
    """Required-role policy fixed by the caller/verifier, never read from index.json."""

    required_roles: frozenset[str]


class BundleReason(Enum):
    """One `verify_layout` finding kind, paired with a path/role in `BundleVerdict.reasons`."""

    OK = "OK"
    MISSING_INDEX = "MISSING_INDEX"
    MISSING_MANIFEST = "MISSING_MANIFEST"
    INDEX_INVALID = "INDEX_INVALID"
    DIGEST_MISMATCH = "DIGEST_MISMATCH"
    MANIFEST_MISMATCH = "MANIFEST_MISMATCH"
    MISSING_ROLE = "MISSING_ROLE"
    EXTRA_BLOB = "EXTRA_BLOB"


@dataclass(frozen=True)
class BundleVerdict:
    """`ok` iff `reasons` is empty; each reason is a `(kind, path_or_role)` pair."""

    ok: bool
    reasons: tuple[tuple[BundleReason, str], ...]


def plan_layout(
    blobs: Sequence[Blob], *, extra_files: Mapping[str, bytes] = {}
) -> dict[str, bytes]:
    """Lay `blobs` out content-addressed with a manifest and index.json.

    Returns `blobs/sha256/<hex>` and `extra_files` paths, `manifest-sha256.txt`
    (BagIt ``"<hex>  <path>\n"`` lines sorted by path, excluding itself and
    index.json), and `index.json` (canonical bytes, of ``{"schema":
    "bundle_index.v1", "descriptors": [...sorted by role]}``). Raises
    `BundleError("DUPLICATE_ROLE:<role>")` on a repeated role."""
    seen_roles: set[str] = set()
    descriptors: list[Descriptor] = []
    files: dict[str, bytes] = {}
    for blob in blobs:
        if blob.role in seen_roles:
            raise BundleError(f"DUPLICATE_ROLE:{blob.role}")
        seen_roles.add(blob.role)
        digest = digest_bytes(blob.data)
        files[f"blobs/sha256/{digest.removeprefix('sha256:')}"] = blob.data
        size = len(blob.data)
        descriptors.append(Descriptor(blob.role, blob.media_type, digest, size))
    files.update(extra_files)

    manifest_text = "".join(
        f"{digest_bytes(data).removeprefix('sha256:')}  {path}\n"
        for path, data in sorted(files.items())
    )
    files[_MANIFEST_PATH] = manifest_text.encode("utf-8")
    files[_INDEX_PATH] = canonical_bytes(
        {
            "schema": "bundle_index.v1",
            "descriptors": [
                {"role": d.role, "mediaType": d.media_type, "digest": d.digest, "size": d.size}
                for d in sorted(descriptors, key=lambda item: item.role)
            ],
        }
    )
    return files


def verify_layout(files: Mapping[str, bytes], expected: ExpectedSet) -> BundleVerdict:
    """Independently re-verify a layout; each check re-derives its own evidence
    from `files` and all run regardless of the others' findings."""
    reasons = [*_check_digests(files), *_check_manifest(files), *_check_index(files, expected)]
    return BundleVerdict(ok=not reasons, reasons=tuple(reasons))


def _check_digests(files: Mapping[str, bytes]) -> list[tuple[BundleReason, str]]:
    """Every `blobs/sha256/<hex>` path's content must hash to its own name."""
    return [
        (BundleReason.DIGEST_MISMATCH, path)
        for path in sorted(files)
        if (match := _BLOB_PATH_RE.match(path))
        and digest_bytes(files[path]).removeprefix("sha256:") != match.group(1)
    ]


def _check_manifest(files: Mapping[str, bytes]) -> list[tuple[BundleReason, str]]:
    """Every file but index.json/the manifest itself must be listed, digest-correct."""
    manifest_data = files.get(_MANIFEST_PATH)
    if manifest_data is None:
        return [(BundleReason.MISSING_MANIFEST, _MANIFEST_PATH)]
    try:
        text = manifest_data.decode("utf-8")
    except UnicodeDecodeError:
        return [(BundleReason.MANIFEST_MISMATCH, _MANIFEST_PATH)]
    lines = (ln.partition("  ") for ln in text.splitlines() if ln)
    declared = {path: hexd for hexd, _, path in lines}
    actual = {
        path: digest_bytes(data).removeprefix("sha256:")
        for path, data in files.items()
        if path not in (_INDEX_PATH, _MANIFEST_PATH)
    }
    return [
        (BundleReason.MANIFEST_MISMATCH, path)
        for path in sorted(actual.keys() | declared.keys())
        if actual.get(path) != declared.get(path)
    ]


def _check_index(
    files: Mapping[str, bytes], expected: ExpectedSet
) -> list[tuple[BundleReason, str]]:
    """MISSING_ROLE/EXTRA_BLOB/INDEX_INVALID; required roles come only from
    `expected` (never index.json) -- this is what defeats the drop attack."""
    index_data = files.get(_INDEX_PATH)
    if index_data is None:
        return [(BundleReason.MISSING_INDEX, _INDEX_PATH)]

    descriptors, findings = _parse_index(index_data)
    roles_present: set[str] = set()
    referenced: set[str] = set()
    for descriptor in descriptors:
        role, digest = descriptor.role, descriptor.digest
        roles_present.add(role)
        hex_digest = digest.removeprefix("sha256:")
        path = f"blobs/sha256/{hex_digest}"
        blob_data = files.get(path)
        if (
            blob_data is None
            or digest_bytes(blob_data) != digest
            or len(blob_data) != descriptor.size
        ):
            findings.append((BundleReason.INDEX_INVALID, role))
        else:
            referenced.add(path)

    missing_roles = expected.required_roles - roles_present
    findings += [(BundleReason.MISSING_ROLE, role) for role in sorted(missing_roles)]
    findings += [
        (BundleReason.EXTRA_BLOB, path)
        for path in sorted(files)
        if _BLOB_PATH_RE.match(path) and path not in referenced
    ]
    return findings


def _is_dict(value: object) -> TypeGuard[dict[str, Any]]:
    """`isinstance(value, dict)`, narrowed to `dict[str, Any]` (not
    `dict[Unknown, Unknown]`) so callers type-check with no `typing.cast`."""
    return isinstance(value, dict)


def _is_list(value: object) -> TypeGuard[list[Any]]:
    """`isinstance(value, list)`, narrowed to `list[Any]` for the same
    reason as `_is_dict` above."""
    return isinstance(value, list)


def _as_str(value: object) -> str | None:
    """Narrow a string-valued index field; malformed types remain absent.

    No coercion or static assertion can turn malformed input into a string."""
    return value if isinstance(value, str) else None


def _index_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
    """Reject ambiguous JSON objects before last-key-wins can discard a field."""
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate index key")
        result[key] = value
    return result


def _parse_index(data: bytes) -> tuple[list[Descriptor], list[tuple[BundleReason, str]]]:
    """Parse the closed bundle_index.v1 structure; any structural
    problem (bad JSON/schema/descriptor) is INDEX_INVALID, and that role then
    also reads as MISSING_ROLE below if required."""
    try:
        raw: Any = json.loads(data, object_pairs_hook=_index_object)
    except ValueError:
        return [], [(BundleReason.INDEX_INVALID, _INDEX_PATH)]
    if not _is_dict(raw):
        return [], [(BundleReason.INDEX_INVALID, _INDEX_PATH)]
    if set(raw) != {"schema", "descriptors"} or raw.get("schema") != "bundle_index.v1":
        return [], [(BundleReason.INDEX_INVALID, _INDEX_PATH)]
    raw_descriptors = raw.get("descriptors")
    if not _is_list(raw_descriptors):
        return [], [(BundleReason.INDEX_INVALID, _INDEX_PATH)]

    descriptors: list[Descriptor] = []
    findings: list[tuple[BundleReason, str]] = []
    roles: set[str] = set()
    for idx, entry in enumerate(raw_descriptors):
        fields = entry if _is_dict(entry) else None
        role = _as_str(fields.get("role")) if fields is not None else None
        digest = _as_str(fields.get("digest")) if fields is not None else None
        media_type = _as_str(fields.get("mediaType")) if fields is not None else None
        size = fields.get("size") if fields is not None else None
        if (
            fields is not None
            and set(fields) == {"role", "mediaType", "digest", "size"}
            and role
            and role not in roles
            and media_type
            and digest is not None
            and _DIGEST_RE.fullmatch(digest) is not None
            and isinstance(size, int)
            and not isinstance(size, bool)
            and size >= 0
        ):
            roles.add(role)
            descriptors.append(Descriptor(role, media_type, digest, size))
        else:
            findings.append((BundleReason.INDEX_INVALID, f"descriptors[{idx}]"))
    return descriptors, findings


# --- CLI -------------------------------------------------------------------------
class _UnsafePathError(Exception):
    """A tar member's path is absolute or contains a ".." segment."""


def _is_unsafe_member_name(name: str) -> bool:
    if not name or name.startswith("/"):
        return True
    return ".." in name.split("/")


def _read_bundle_tar(path: str) -> dict[str, bytes]:
    files: dict[str, bytes] = {}
    with tarfile.open(path, mode="r:") as tar:
        for member in tar.getmembers():
            if _is_unsafe_member_name(member.name):
                raise _UnsafePathError(member.name)
            if not member.isfile():
                continue
            extracted = tar.extractfile(member)
            if extracted is None:
                raise _UnsafePathError(member.name)
            files[member.name] = extracted.read()
    return files


def _blob_for_role(
    descriptors: list[Descriptor], files: dict[str, bytes], role: str
) -> bytes | None:
    for descriptor in descriptors:
        candidate_role, digest = descriptor.role, descriptor.digest
        if candidate_role != role:
            continue
        blob = files.get(f"blobs/sha256/{digest.removeprefix('sha256:')}")
        if blob is not None and digest_bytes(blob) == digest:
            return blob
    return None


def _chain_rows_from_json(data: bytes) -> list[ChainRow]:
    raw: Any = json.loads(data)
    if not isinstance(raw, list):
        raise ValueError("ledger_chain blob is not a JSON list")
    rows: list[ChainRow] = []
    for entry in cast("list[Any]", raw):
        if not isinstance(entry, dict):
            raise ValueError("ledger_chain row is not a JSON object")
        row = cast("dict[str, Any]", entry)
        seq, kind, payload_digest = row["seq"], row["kind"], row["payload_digest"]
        prev_hash, row_hash = row.get("prev_hash"), row["row_hash"]
        if not (
            isinstance(seq, int)
            and isinstance(kind, str)
            and isinstance(payload_digest, str)
            and (prev_hash is None or isinstance(prev_hash, str))
            and isinstance(row_hash, str)
        ):
            raise ValueError("ledger_chain row has a malformed field type")
        rows.append(
            ChainRow(
                seq=seq,
                kind=kind,
                payload_digest=payload_digest,
                prev_hash=prev_hash,
                row_hash=row_hash,
            )
        )
    return rows


def _anchor_from_json(data: bytes) -> AnchorRecord:
    raw: Any = json.loads(data)
    if not isinstance(raw, dict):
        raise ValueError("anchor blob is not a JSON object")
    payload = cast("dict[str, Any]", raw)
    upto_seq, chain_hash = payload["upto_seq"], payload["chain_hash"]
    if not (isinstance(upto_seq, int) and isinstance(chain_hash, str)):
        raise ValueError("anchor blob has a malformed field type")
    return AnchorRecord(upto_seq=upto_seq, chain_hash=chain_hash)


def _resolve_anchor(
    descriptors: list[Descriptor],
    files: dict[str, bytes],
    reasons: list[tuple[str, str]],
) -> AnchorRecord | None:
    anchor_blob = _blob_for_role(descriptors, files, "anchor")
    if anchor_blob is None:
        return None
    try:
        return _anchor_from_json(anchor_blob)
    except (ValueError, KeyError, TypeError):
        reasons.append(("ANCHOR_UNPARSEABLE", "anchor"))
        return None


def _resolve_chain(
    descriptors: list[Descriptor], files: dict[str, bytes]
) -> tuple[list[tuple[str, str]], str]:
    reasons: list[tuple[str, str]] = []
    chain_blob = _blob_for_role(descriptors, files, "ledger_chain")
    if chain_blob is None:
        return reasons, "not_measured"
    try:
        rows = _chain_rows_from_json(chain_blob)
    except (ValueError, KeyError, TypeError):
        return [("CHAIN_UNPARSEABLE", "ledger_chain")], "not_measured"

    anchor_record = _resolve_anchor(descriptors, files, reasons)
    chain_verdict = verify_chain(rows, anchor=anchor_record)
    if not chain_verdict.ok:
        reasons.append((chain_verdict.reason.value, str(chain_verdict.at_seq)))
        return reasons, "not_measured"
    return reasons, ("anchored" if anchor_record is not None else "not_measured")


def _resolve_raw_included(
    descriptors: list[Descriptor], files: dict[str, bytes]
) -> tuple[str, list[tuple[str, str]]]:
    receipt_blob = _blob_for_role(descriptors, files, "receipt")
    if receipt_blob is None:
        return "not_measured", []
    try:
        statement: Any = json.loads(receipt_blob)
        predicate = cast("dict[str, Any]", statement)["predicate"]
        limitations = cast("dict[str, Any]", predicate)["limitations"]
        raw_included = cast("dict[str, Any]", limitations)["raw_included"]
    except (ValueError, KeyError, TypeError):
        return "not_measured", [("RECEIPT_UNPARSEABLE", "receipt")]
    if not isinstance(raw_included, str):
        return "not_measured", [("RECEIPT_UNPARSEABLE", "receipt")]
    return raw_included, []


def _report_shape(
    *, integrity: str, reasons: list[tuple[str, str]], raw_included: str, ledger_anchored: str
) -> dict[str, object]:
    return {
        "schema": "verify_report.v1",
        "integrity": integrity,
        "reasons": [[code, detail] for code, detail in reasons],
        "signature_verification": "not_measured",
        "raw_included": raw_included,
        "ledger_anchored": ledger_anchored,
        "authenticity": "not asserted",
        "honesty_note": (
            "This verifier does not assert issuer authenticity. Signature "
            "verification is a separate, optional step (verify --signatures)."
        ),
    }


def _finish(
    *, reasons: list[tuple[str, str]], raw_included: str, ledger_anchored: str
) -> tuple[dict[str, object], int]:
    integrity = "PASS" if not reasons else "FAIL"
    report = _report_shape(
        integrity=integrity,
        reasons=reasons,
        raw_included=raw_included,
        ledger_anchored=ledger_anchored,
    )
    return report, (0 if integrity == "PASS" else 1)


def _build_report(
    bundle_path: str, expected_roles: frozenset[str]
) -> tuple[dict[str, object], int]:
    try:
        files = _read_bundle_tar(bundle_path)
    except _UnsafePathError as exc:
        return _finish(
            reasons=[("UNSAFE_PATH", str(exc))],
            raw_included="not_measured",
            ledger_anchored="not_measured",
        )

    bundle_verdict = verify_layout(files, ExpectedSet(required_roles=expected_roles))
    reasons = [(reason.value, detail) for reason, detail in bundle_verdict.reasons]

    descriptors: list[Descriptor] = []
    index_data = files.get("index.json")
    if index_data is not None:
        descriptors, _index_findings = _parse_index(index_data)

    chain_reasons, ledger_anchored = _resolve_chain(descriptors, files)
    reasons.extend(chain_reasons)

    raw_included, receipt_reasons = _resolve_raw_included(descriptors, files)
    reasons.extend(receipt_reasons)

    return _finish(reasons=reasons, raw_included=raw_included, ledger_anchored=ledger_anchored)


def _print_human_summary(report: dict[str, object]) -> None:
    print(f"integrity: {report['integrity']}")
    reasons = cast("list[list[str]]", report["reasons"])
    if reasons:
        print("reasons:")
        for code, detail in reasons:
            print(f"  {code}: {detail}")
    print(f"signature_verification: {report['signature_verification']}")
    print(f"raw_included: {report['raw_included']}")
    print(f"ledger_anchored: {report['ledger_anchored']}")
    print(f"authenticity: {report['authenticity']}")
    print(str(report["honesty_note"]))


def _build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="verify.py",
        description=(
            "Standalone, install-free content-integrity verifier for an "
            "underwrite export bundle (stdlib only)."
        ),
    )
    parser.add_argument("bundle", help="Path to the bundle tar file.")
    parser.add_argument(
        "--expected-roles",
        default="receipt",
        help="Comma-separated required index.json roles (default: receipt).",
    )
    parser.add_argument(
        "--json", action="store_true", help="Print only the machine-readable JSON report."
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    args = _build_arg_parser().parse_args(argv)
    expected_roles = frozenset(
        role.strip() for role in str(args.expected_roles).split(",") if role.strip()
    )
    report, exit_code = _build_report(str(args.bundle), expected_roles)
    if args.json:
        print(json.dumps(report))
    else:
        _print_human_summary(report)
    return exit_code


if __name__ == "__main__":
    sys.exit(main())
